contract MevBot is FlashLoanSimpleReceiverBase {
    address public owner;

    constructor(IPoolAddressesProvider _addressProvider) FlashLoanSimpleReceiverBase(_addressProvider) {
        owner = msg.sender;
    }

    function requestFlashLoan(address _token, uint256 _amount) external {
        address receiverAddress = address(this);
        address asset = _token;
        uint256 amount = _amount;
