"use client";

import React, { useState } from "react";
import { updateOrder } from "@/app/BookAPI";
import Link from "next/link";
import { useRouter } from "next/router";

const UpdateOrderPage = ({ id, initialCustomerName }) => {
  const [customerName, setCustomerName] = useState(initialCustomerName);
  const router = useRouter();

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const orderStatus = await updateOrder(id, customerName);
      console.log(orderStatus);
      router.push("/"); // Redirect to homepage or any other page after successful update
