            <input
              type="text"
              value={customerName}
              onChange={(e) => setCustomerName(e.target.value)}
            />
          </label>
          <button type="submit">Update Order</button>
        </form>
      </div>
    </div>
  );
};

export async function getServerSideProps({ params }) {
  const { id } = params;

  // Fetch initial customer name or any other data you need from your API
  const res = await fetch(`https://your-api-url.com/orders/${id}`);
  const orderData = await res.json();
  const initialCustomerName = orderData.customerName || "";

  return {
    props: {
      id,
