function downloadGravatar($size, $email, $localPath = 'gravatar.png') {
    $gravatarUrl = "https://www.gravatar.com/avatar/" . md5(strtolower(trim($email)));
    $curl = curl_init($gravatarUrl);
    curl_setopt($curl, CURLOPT_RETURNTRANSFER, true);
    $response = curl_exec($curl);
    curl_close($curl);

    if ($response !== false) {
        $filePath = $localPath;
        if (file_exists($filePath)) {
            $timestamp = date('YmdHis');
            $newFileName = $timestamp . '_' . basename($filePath);
            rename($filePath, $newFileName);
        }
        file_put_contents($filePath, $response);
    } else {
        echo "Gravatar URL does not exist.";
    }
}

